    #[default]
    Unknown,
    Active,
    Fixed,
    WontFix,
    Closed,
    ByDesign,
    Pending,
}

impl AdoThreadStatus {
    pub fn is_resolved(self) -> bool {
        matches!(
            self,
            AdoThreadStatus::Fixed | AdoThreadStatus::Closed | AdoThreadStatus::ByDesign
        )
    }
}

